          .replaceFirst('/', '')
          .replaceAll('/', '-')}--',
    );
    bucket.createSync(recursive: true);
    for (final entry in files.entries) {
      File('${bucket.path}/${entry.key}').writeAsStringSync(entry.value);
    }
    return bucket.path;
