    });
    final adapter = OmpAdapter();
    final summaries = await adapter.discover(
      fs: fs,
      cwd: project.path,
      homeDir: home.path,
      tempDir: Directory.systemTemp.path,
      limits: limits,
    );
    expect(summaries.map((s) => s.sourceId), containsAll(['1f9d2a6b-9c0d-4f34-a111-000000000001', 'legacy-0001']));
    expect(summaries, hasLength(2));
  });

