+  for (var i = 0; i < args.length; i++) {
+    final arg = args[i];
+    if (arg == '--all') {
+      operands.all = true;
+      continue;
+    }
+    String? value;
+    String? name;
+    for (final flag in const ['--harness', '--session-root', '--cwd', '--session']) {
