+      MenuItem(
+        key: 'omp',
+        label: 'omp',
+        description: '~/.omp/agent/sessions — pinned format',
+      ),
+      MenuItem(
+        key: 'claude',
+        label: 'claude',
+        description: '~/.claude/projects — partial pin (taxonomy spike open)',
+      ),
+      MenuItem(
