+      discovered = await adapter.discover(
+        fs: _env,
+        cwd: _env.cwd,
+        homeDir: home,
+        tempDir: '',
+        limits: const ImportLimits(),
+      );
+    } on ForeignStoreAbsent catch (error) {
+      io.writeln(
+        _keyStatusView.errorLine(
