+      io.writeln(
+        _keyStatusView.errorLine(
+          'import: ${error.message}',
+          _agent.state.model.baseUrl,
+        ),
+      );
+      return;
+    }
+    if (discovered.isEmpty) {
+      io.writeln(
+        'import: no ${adapter.id} sessions found for ${_env.cwd}',
+      );
+      return;
+    }
