+    final described = <ForeignSessionSummary>[];
+    for (final summary in discovered) {
+      try {
+        described.add(
+          await describeForeignSession(
+            adapter: adapter,
+            fs: _env,
+            summary: summary,
+            limits: const ImportLimits(),
+            homeDir: home,
