+        'not importable yet.',
+      );
+      return;
+    }
+    final adapter = adapterFor(key);
+    if (adapter == null) return;
+    final home = config.homeDir ?? '';
+    final List<ForeignSessionSummary> discovered;
+    try {
+      discovered = await adapter.discover(
+        fs: _env,
+        cwd: _env.cwd,
+        homeDir: home,
+        tempDir: '',
+        limits: const ImportLimits(),
+      );
